using System;
using Betta.Interfaces;
using Rhino.Geometry;

namespace Facade
{
    /// <summary>
    /// One four-sided facade panel. Opaque (IBettaValue), so it travels between
    /// components as a single "Panel" wire rather than exploding into properties.
    /// Corners are in order around the panel.
    /// </summary>
    public sealed class Panel : IBettaValue
    {
        private readonly Point3d[] _corners;
        private readonly double[] _edges;
        private readonly double[] _diagonals;

        public Panel(Point3d[] corners, int index)
        {
            if (corners == null || corners.Length != 4)
                throw new ArgumentException("A panel needs exactly four corners.", nameof(corners));

            _corners = (Point3d[])corners.Clone();
            Index = index;

            _edges = new double[4];
            for (int i = 0; i < 4; i++)
                _edges[i] = _corners[i].DistanceTo(_corners[(i + 1) % 4]);

            _diagonals = new[]
            {
                _corners[0].DistanceTo(_corners[2]),
                _corners[1].DistanceTo(_corners[3]),
            };

            // Width: mean of edges 1 and 3; height: mean of edges 2 and 4.
            Width = (_edges[0] + _edges[2]) / 2.0;
            Height = (_edges[1] + _edges[3]) / 2.0;

            Center = new Point3d(
                (_corners[0].X + _corners[1].X + _corners[2].X + _corners[3].X) / 4.0,
                (_corners[0].Y + _corners[1].Y + _corners[2].Y + _corners[3].Y) / 4.0,
                (_corners[0].Z + _corners[1].Z + _corners[2].Z + _corners[3].Z) / 4.0);

            // Two triangles, which is exact for a planar quad.
            Area = TriangleArea(_corners[0], _corners[1], _corners[2])
                 + TriangleArea(_corners[0], _corners[2], _corners[3]);

            Deviation = ComputeDeviation(_corners);
        }

        public int Index { get; }

        public double Area { get; }

        public Point3d Center { get; }

        /// <summary>Distance from the fourth corner to the plane through the first three.</summary>
        public double Deviation { get; }

        /// <summary>Mean of edges 1 and 3.</summary>
        public double Width { get; }

        /// <summary>Mean of edges 2 and 4.</summary>
        public double Height { get; }

        public Point3d[] Corners => (Point3d[])_corners.Clone();

        /// <summary>Edge lengths in order: c0-c1, c1-c2, c2-c3, c3-c0.</summary>
        public double[] Edges => (double[])_edges.Clone();

        /// <summary>Diagonal lengths: c0-c2, c1-c3.</summary>
        public double[] Diagonals => (double[])_diagonals.Clone();

        /// <summary>A new closed polyline through the four corners.</summary>
        public Curve CreateOutline()
        {
            return new PolylineCurve(new[] { _corners[0], _corners[1], _corners[2], _corners[3], _corners[0] });
        }

        private static double TriangleArea(Point3d a, Point3d b, Point3d c)
        {
            return 0.5 * Vector3d.CrossProduct(b - a, c - a).Length;
        }

        private static double ComputeDeviation(Point3d[] c)
        {
            var normal = Vector3d.CrossProduct(c[1] - c[0], c[2] - c[0]);
            // Three collinear corners define no plane; treat such a panel as flat.
            if (normal.Length < 1e-12) return 0.0;
            normal.Unitize();

            var d = c[3] - c[0];
            return Math.Abs(d.X * normal.X + d.Y * normal.Y + d.Z * normal.Z);
        }
    }
}

