using System;
using System.Collections.Generic;
using Betta.Attributes;
using Betta.Interfaces;
using Rhino.Geometry;

namespace Facade
{
    [GrasshopperCollection("Facade", "Panels")]
    public interface IPanelTools : IBettaCollection
    {
        [GrasshopperMethod("Panelize Surface", "Cuts a surface into an evenly spaced grid of four-sided panels")]
        (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(
            [GrasshopperParameter("Surface")] Surface surface,
            [GrasshopperParameter("U Count", DefaultValue = 10)] int uCount,
            [GrasshopperParameter("V Count", DefaultValue = 6)] int vCount);

        [GrasshopperMethod("Panel Info", "Corners, outline, area, center and index of one panel")]
        (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(
            [GrasshopperParameter("Panel")] Panel panel);
    }

    public class PanelTools : IPanelTools
    {
        public (List<Panel> Panels, List<Curve> Outlines) PanelizeSurface(Surface surface, int uCount, int vCount)
        {
            if (surface == null) throw new ArgumentNullException(nameof(surface));
            if (uCount < 1 || vCount < 1)
                throw new ArgumentException($"U Count and V Count must be at least 1 (got {uCount} and {vCount}).");

            Interval du = surface.Domain(0);
            Interval dv = surface.Domain(1);

            var panels = new List<Panel>(uCount * vCount);
            var outlines = new List<Curve>(uCount * vCount);

            for (int j = 0; j < vCount; j++)
            {
                double v0 = dv.T0 + dv.Length * j / vCount;
                double v1 = dv.T0 + dv.Length * (j + 1) / vCount;

                for (int i = 0; i < uCount; i++)
                {
                    double u0 = du.T0 + du.Length * i / uCount;
                    double u1 = du.T0 + du.Length * (i + 1) / uCount;

                    var corners = new[]
                    {
                        surface.PointAt(u0, v0),
                        surface.PointAt(u1, v0),
                        surface.PointAt(u1, v1),
                        surface.PointAt(u0, v1),
                    };

                    var panel = new Panel(corners, i + j * uCount);
                    panels.Add(panel);
                    outlines.Add(panel.CreateOutline());
                }
            }

            return (panels, outlines);
        }

        public (List<Point3d> Corners, Curve Outline, double Area, Point3d Center, int Index) PanelInfo(Panel panel)
        {
            if (panel == null) throw new ArgumentNullException(nameof(panel));
            return (new List<Point3d>(panel.Corners), panel.CreateOutline(), panel.Area, panel.Center, panel.Index);
        }
    }
}

