using System;
using System.Collections.Generic;
using Betta.Attributes;
using Betta.Interfaces;

namespace Facade
{
    [GrasshopperCollection("Facade", "Analysis")]
    public interface IPanelAnalysis : IBettaCollection
    {
        [GrasshopperMethod("Planarity", "Deviation of each panel's fourth corner from the plane of the other three")]
        (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance,
            IBettaReport report);

        [GrasshopperMethod("Classify Panels", "Labels each panel flat, cold-bent or custom by its deviation")]
        (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 0.5)] double tolerance);

        [GrasshopperMethod("Panel Stats", "Total, minimum, maximum and mean panel area")]
        (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(
            [GrasshopperParameter("Panels")] List<Panel> panels);
    }

    public class PanelAnalysis : IPanelAnalysis
    {
        public (List<double> Deviation, List<bool> Flat, int FlatCount) Planarity(
            List<Panel> panels, double tolerance, IBettaReport report)
        {
            if (panels == null) throw new ArgumentNullException(nameof(panels));

            var deviation = new List<double>(panels.Count);
            var flat = new List<bool>(panels.Count);
            int flatCount = 0;

            foreach (var panel in panels)
            {
                deviation.Add(panel.Deviation);
                bool isFlat = panel.Deviation <= tolerance;
                flat.Add(isFlat);
                if (isFlat) flatCount++;
            }

            int notFlat = panels.Count - flatCount;
            if (notFlat * 2 > panels.Count)
                report.Warning($"{notFlat} of {panels.Count} panels are not flat (deviation above {tolerance})");

            return (deviation, flat, flatCount);
        }

        public (List<string> Type, int FlatCount, int ColdBentCount, int CustomCount) ClassifyPanels(
            List<Panel> panels, double tolerance)
        {
            if (panels == null) throw new ArgumentNullException(nameof(panels));

            var types = new List<string>(panels.Count);
            int flat = 0, coldBent = 0, custom = 0;

            foreach (var panel in panels)
            {
                double d = panel.Deviation;
                if (d <= tolerance)
                {
                    types.Add("flat");
                    flat++;
                }
                else if (d <= 10.0 * tolerance)
                {
                    types.Add("cold-bent");
                    coldBent++;
                }
                else
                {
                    types.Add("custom");
                    custom++;
                }
            }

            return (types, flat, coldBent, custom);
        }

        public (double TotalArea, double MinArea, double MaxArea, double MeanArea) PanelStats(List<Panel> panels)
        {
            if (panels == null || panels.Count == 0)
                throw new ArgumentException("Panel Stats needs at least one panel.");

            double total = 0, min = double.MaxValue, max = double.MinValue;
            foreach (var panel in panels)
            {
                double a = panel.Area;
                total += a;
                if (a < min) min = a;
                if (a > max) max = a;
            }

            return (total, min, max, total / panels.Count);
        }
    }
}

