using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace Facade.Nesting
{
    /// <summary>A placed rectangle in sheet-local coordinates (sheet origin at 0,0).</summary>
    internal sealed class PlacedRect
    {
        public int Sheet;
        public double X;
        public double Y;
        public double Width;
        public double Height;
    }

    internal sealed class NestResult
    {
        public List<PlacedRect> Placed = new List<PlacedRect>();
        public int SheetCount;
        public int Unplaced;
        public double Utilization;
    }

    /// <summary>
    /// Shelf packer for panel rectangles. Parts are placed tallest first, filling each shelf
    /// left to right. A part that does not fit starts a new shelf above; a shelf that does not
    /// fit starts a new sheet. A part is turned 90 degrees only when it fits turned and not as given.
    /// Pure geometry: no Grasshopper or Betta types.
    /// </summary>
    internal static class ShelfNester
    {
        public static NestResult Nest(
            IReadOnlyList<Panel> panels,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            IProgress<int> progress,
            CancellationToken ct)
        {
            var packer = new Packer(sheetWidth, sheetHeight, spacing);
            var result = new NestResult();

            var order = Enumerable.Range(0, panels.Count)
                .OrderByDescending(i => panels[i].Height)
                .ThenByDescending(i => panels[i].Width)
                .ToList();

            for (int n = 0; n < order.Count; n++)
            {
                ct.ThrowIfCancellationRequested();

                var panel = panels[order[n]];
                if (packer.TryPlace(panel.Width, panel.Height, out PlacedRect rect))
                    result.Placed.Add(rect);
                else
                    result.Unplaced++;

                progress?.Report((n + 1) * 100 / order.Count);
            }

            result.SheetCount = packer.Sheets.Count;
            if (result.SheetCount > 0)
            {
                double placedArea = result.Placed.Sum(r => r.Width * r.Height);
                result.Utilization = placedArea / (result.SheetCount * sheetWidth * sheetHeight);
            }

            return result;
        }

        private sealed class Shelf
        {
            public double Y;
            public double Height;
            public double NextX;
        }

        private sealed class Sheet
        {
            public readonly List<Shelf> Shelves = new List<Shelf>();
        }

        private sealed class Packer
        {
            private readonly double _width;
            private readonly double _height;
            private readonly double _gap;

            public readonly List<Sheet> Sheets = new List<Sheet>();

            public Packer(double width, double height, double gap)
            {
                _width = width;
                _height = height;
                _gap = gap;
            }

            public bool TryPlace(double width, double height, out PlacedRect placed)
            {
                placed = null;
                var orientations = new[] { (W: width, H: height), (W: height, H: width) };
                Sheet current = Sheets.Count > 0 ? Sheets[Sheets.Count - 1] : null;
                int sheetIndex = Sheets.Count - 1;

                // 1. Continue the last shelf on the current sheet.
                if (current != null && current.Shelves.Count > 0)
                {
                    Shelf shelf = current.Shelves[current.Shelves.Count - 1];
                    foreach (var o in orientations)
                    {
                        if (o.H <= shelf.Height && shelf.NextX + o.W + _gap <= _width)
                        {
                            placed = Make(sheetIndex, shelf.NextX, shelf.Y, o.W, o.H);
                            shelf.NextX += o.W + _gap;
                            return true;
                        }
                    }
                }

                // 2. Start a new shelf above the last one on the current sheet.
                if (current != null)
                {
                    Shelf last = current.Shelves.Count > 0 ? current.Shelves[current.Shelves.Count - 1] : null;
                    double y = last == null ? _gap : last.Y + last.Height + _gap;

                    foreach (var o in orientations)
                    {
                        if (o.W + 2 * _gap <= _width && y + o.H + _gap <= _height)
                        {
                            current.Shelves.Add(new Shelf { Y = y, Height = o.H, NextX = _gap + o.W + _gap });
                            placed = Make(sheetIndex, _gap, y, o.W, o.H);
                            return true;
                        }
                    }
                }

                // 3. Start a new sheet.
                foreach (var o in orientations)
                {
                    if (o.W + 2 * _gap <= _width && o.H + 2 * _gap <= _height)
                    {
                        var sheet = new Sheet();
                        sheet.Shelves.Add(new Shelf { Y = _gap, Height = o.H, NextX = _gap + o.W + _gap });
                        Sheets.Add(sheet);
                        placed = Make(Sheets.Count - 1, _gap, _gap, o.W, o.H);
                        return true;
                    }
                }

                return false;
            }

            private static PlacedRect Make(int sheet, double x, double y, double w, double h)
            {
                return new PlacedRect { Sheet = sheet, X = x, Y = y, Width = w, Height = h };
            }
        }
    }
}

