using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Betta.Attributes;
using Betta.Interfaces;
using Facade.Nesting;
using Rhino.Geometry;

namespace Facade
{
    [GrasshopperCollection("Facade", "Fabrication")]
    public interface IPanelFabrication : IBettaCollection
    {
        [GrasshopperMethod("Group Identical Panels", "Numbers panels whose edge and diagonal lengths match within Tolerance")]
        (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Tolerance", DefaultValue = 1.0)] double tolerance);

        [GrasshopperMethod("Nest On Sheets", "Shelf-packs panel rectangles onto sheets, running in the background")]
        Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Sheet Width", DefaultValue = 3000.0)] double sheetWidth,
            [GrasshopperParameter("Sheet Height", DefaultValue = 1500.0)] double sheetHeight,
            [GrasshopperParameter("Spacing", DefaultValue = 10.0)] double spacing,
            IProgress<int> progress,
            CancellationToken cancellationToken,
            IBettaReport report);

        [GrasshopperMethod("Cut List", "CSV of index, width, height, area and deviation per panel; optionally writes it to Path")]
        (string CSV, bool Written) CutList(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Path", DefaultValue = "")] string path,
            [GrasshopperParameter("Write", DefaultValue = false)] bool write);
    }

    public class PanelFabrication : IPanelFabrication
    {
        /// <summary>Gap between sheets along X in the nested Outlines.</summary>
        private const double SheetSeparation = 100.0;

        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            if (panels == null) throw new ArgumentNullException(nameof(panels));

            var groups = new List<int>(panels.Count);
            var representatives = new List<Panel>();
            var signatures = new List<double[]>();

            foreach (var panel in panels)
            {
                double[] signature = Signature(panel);

                int found = -1;
                for (int g = 0; g < signatures.Count && found < 0; g++)
                {
                    if (SameWithin(signature, signatures[g], tolerance)) found = g;
                }

                if (found < 0)
                {
                    representatives.Add(panel);
                    signatures.Add(signature);
                    found = representatives.Count - 1;
                }

                groups.Add(found);
            }

            return (groups, representatives.Count, representatives);
        }

        public Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            IProgress<int> progress,
            CancellationToken cancellationToken,
            IBettaReport report)
        {
            return NestOnSheetsAsync(panels, sheetWidth, sheetHeight, spacing, progress, cancellationToken, report);
        }

        private static async Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheetsAsync(
            List<Panel> panels,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            IProgress<int> progress,
            CancellationToken cancellationToken,
            IBettaReport report)
        {
            if (panels == null) throw new ArgumentNullException(nameof(panels));
            if (sheetWidth <= 0 || sheetHeight <= 0)
                throw new ArgumentException($"Sheet Width and Sheet Height must be positive (got {sheetWidth} x {sheetHeight}).");
            if (spacing < 0)
                throw new ArgumentException($"Spacing cannot be negative (got {spacing}).");

            NestResult result = await Task.Run(
                () => ShelfNester.Nest(panels, sheetWidth, sheetHeight, spacing, progress, cancellationToken),
                cancellationToken);

            if (result.Unplaced > 0)
                report.Warning($"{result.Unplaced} of {panels.Count} panels fit on no sheet");

            var outlines = new List<Curve>(result.Placed.Count);
            var sheets = new List<int>(result.Placed.Count);
            foreach (var rect in result.Placed)
            {
                double ox = rect.Sheet * (sheetWidth + SheetSeparation);
                double x0 = ox + rect.X;
                double x1 = x0 + rect.Width;
                double y0 = rect.Y;
                double y1 = y0 + rect.Height;

                outlines.Add(new PolylineCurve(new[]
                {
                    new Point3d(x0, y0, 0),
                    new Point3d(x1, y0, 0),
                    new Point3d(x1, y1, 0),
                    new Point3d(x0, y1, 0),
                    new Point3d(x0, y0, 0),
                }));
                sheets.Add(rect.Sheet);
            }

            return (outlines, sheets, result.SheetCount, result.Utilization);
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (panels == null) throw new ArgumentNullException(nameof(panels));

            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder();
            sb.AppendLine("Index,Width,Height,Area,Deviation");
            foreach (var p in panels)
            {
                sb.AppendLine(string.Join(",",
                    p.Index.ToString(inv),
                    p.Width.ToString("F3", inv),
                    p.Height.ToString("F3", inv),
                    p.Area.ToString("F3", inv),
                    p.Deviation.ToString("F3", inv)));
            }

            string csv = sb.ToString();
            if (!write) return (csv, false);

            if (string.IsNullOrWhiteSpace(path))
                throw new ArgumentException("Write is true but Path is empty. Set Path to a file name to write the CSV.");

            File.WriteAllText(path, csv, Encoding.UTF8);
            return (csv, true);
        }

        /// <summary>Sorted edge lengths followed by sorted diagonal lengths (six values).</summary>
        private static double[] Signature(Panel panel)
        {
            var edges = panel.Edges;
            var diagonals = panel.Diagonals;
            Array.Sort(edges);
            Array.Sort(diagonals);
            return edges.Concat(diagonals).ToArray();
        }

        private static bool SameWithin(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
            {
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            }
            return true;
        }
    }
}

